from datetime import date, datetime


def reconcile(bank, ledger, window=2):
    def parse_date(value):
        v = value.strip()
        if v.endswith('Z'):
            v = v[:-1]
        if 'T' in v or ' ' in v:
            return datetime.fromisoformat(v.replace('Z', '+00:00')).date()
        return date.fromisoformat(v)

    parsed_bank = [
        (index, item_id, parse_date(item_date), amount)
        for index, (item_id, item_date, amount) in enumerate(bank)
    ]
    parsed_ledger = [
        (index, item_id, parse_date(item_date), amount)
        for index, (item_id, item_date, amount) in enumerate(ledger)
    ]

    ordered_bank = sorted(parsed_bank, key=lambda item: (item[2], item[1]))
    ordered_ledger = sorted(parsed_ledger, key=lambda item: (item[2], item[1]))

    matched_bank_indices = set()
    matched_ledger_indices = set()
    matches = []

    for bank_index, bank_id, bank_date, bank_amount in ordered_bank:
        for ledger_index, ledger_id, ledger_date, ledger_amount in ordered_ledger:
            if ledger_index in matched_ledger_indices:
                continue
            if bank_amount == ledger_amount and abs((bank_date - ledger_date).days) <= window:
                matches.append((bank_id, ledger_id))
                matched_bank_indices.add(bank_index)
                matched_ledger_indices.add(ledger_index)
                break

    unmatched_bank = [
        item_id for index, item_id, _, _ in parsed_bank
        if index not in matched_bank_indices
    ]
    unmatched_ledger = [
        item_id for index, item_id, _, _ in parsed_ledger
        if index not in matched_ledger_indices
    ]

    return matches, unmatched_bank, unmatched_ledger
